1 | #!/usr/bin/env node
2 | /**
3 |  * BreakPoint AI — Red Team / Blue Team / Judge Orchestrator
4 |  *
5 |  * Drives the adversarial loop:
6 |  *   Round N:
7 |  *     1. Red Team  → runs npm test, emits ATTACK REPORT JSON
8 |  *     2. Blue Team → patches routes/transfer.js, emits PATCH REPORT JSON
9 |  *     3. Judge     → evaluates both reports, emits JUDGE VERDICT JSON
10 |  *     4. If verdict === "APPROVED"  → exit 0
11 |  *        If verdict === "REJECTED"  → next round (max MAX_ROUNDS)
12 |  *
13 |  * Prerequisites:
14 |  *   - Node.js 18+ (uses native fetch)
15 |  *   - WATSONX_API_KEY env var  (IBM watsonx.ai API key)
16 |  *   - WATSONX_PROJECT_ID env var
17 |  *   - WATSONX_URL env var (default: https://us-south.ml.cloud.ibm.com)
18 |  *   - MODEL_ID env var (default: ibm/granite-3-3-8b-instruct)
19 |  *
20 |  * Usage:
21 |  *   node orchestrate.js [--rounds <n>] [--demo-app <path>]
22 |  */
23 | 
24 | 'use strict';
25 | 
26 | const fs   = require('fs');
27 | const path = require('path');
28 | const { execSync, spawnSync } = require('child_process');
29 | 
30 | // ---------------------------------------------------------------------------
31 | // Configuration
32 | // ---------------------------------------------------------------------------
33 | 
34 | const MAX_ROUNDS    = parseInt(process.env.MAX_ROUNDS  || '5', 10);
35 | const DEMO_APP_DIR  = path.resolve(
36 |   process.env.DEMO_APP_PATH ||
37 |   path.join(__dirname, '..', 'demo-app')
38 | );
39 | const REPORT_DIR    = path.join(__dirname, '..', 'audit-reports');
40 | const ROUTE_FILE    = path.join(DEMO_APP_DIR, 'routes', 'transfer.js');
41 | const OPENAPI_FILE  = path.join(DEMO_APP_DIR, 'openapi.json');
42 | const FUZZING_FILE  = path.join(DEMO_APP_DIR, 'tests', 'generated_fuzzing.test.js');
43 | const CONCURRENCY_FILE = path.join(DEMO_APP_DIR, 'tests', 'generated_concurrency.test.js');
44 | 
45 | const WATSONX_URL      = process.env.WATSONX_URL || 'https://us-south.ml.cloud.ibm.com';
46 | const WATSONX_API_KEY  = process.env.WATSONX_API_KEY;
47 | const WATSONX_PROJECT  = process.env.WATSONX_PROJECT_ID;
48 | const MODEL_ID         = process.env.MODEL_ID || 'ibm/granite-3-3-8b-instruct';
49 | 
50 | const IAM_TOKEN_URL = 'https://iam.cloud.ibm.com/identity/token';
51 | 
52 | // ---------------------------------------------------------------------------
53 | // IAM token cache
54 | // ---------------------------------------------------------------------------
55 | 
56 | let _iamToken = null;
57 | let _iamExpiry = 0;
58 | 
59 | async function getIAMToken() {
60 |   if (_iamToken && Date.now() < _iamExpiry) return _iamToken;
61 | 
62 |   if (!WATSONX_API_KEY) {
63 |     throw new Error('WATSONX_API_KEY environment variable is not set.');
64 |   }
65 | 
66 |   const body = new URLSearchParams({
67 |     grant_type: 'urn:ibm:params:oauth:grant-type:apikey',
68 |     apikey: WATSONX_API_KEY,
69 |   });
70 | 
71 |   const resp = await fetch(IAM_TOKEN_URL, {
72 |     method: 'POST',
73 |     headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
74 |     body: body.toString(),
75 |   });
76 | 
77 |   if (!resp.ok) {
78 |     const text = await resp.text();
79 |     throw new Error(`IAM token request failed (${resp.status}): ${text}`);
80 |   }
81 | 
82 |   const json = await resp.json();
83 |   _iamToken  = json.access_token;
84 |   // Expire 5 minutes before the token actually expires
85 |   _iamExpiry = Date.now() + (json.expires_in - 300) * 1000;
86 |   return _iamToken;
87 | }
88 | 
89 | // ---------------------------------------------------------------------------
90 | // watsonx.ai chat completion
91 | // ---------------------------------------------------------------------------
92 | 
93 | async function chat(systemPrompt, userMessage) {
94 |   if (!WATSONX_PROJECT) {
95 |     throw new Error('WATSONX_PROJECT_ID environment variable is not set.');
96 |   }
97 | 
98 |   const token = await getIAMToken();
99 | 
100 |   const endpoint = `${WATSONX_URL}/ml/v1/text/chat?version=2024-05-31`;
101 | 
102 |   const payload = {
103 |     model_id: MODEL_ID,
104 |     project_id: WATSONX_PROJECT,
105 |     messages: [
106 |       { role: 'system', content: systemPrompt },
107 |       { role: 'user',   content: userMessage  },
108 |     ],
109 |     parameters: {
110 |       max_new_tokens: 4096,
111 |       temperature: 0.2,
112 |     },
113 |   };
114 | 
115 |   const resp = await fetch(endpoint, {
116 |     method: 'POST',
117 |     headers: {
118 |       'Content-Type':  'application/json',
119 |       'Authorization': `Bearer ${token}`,
120 |     },
121 |     body: JSON.stringify(payload),
122 |   });
123 | 
124 |   if (!resp.ok) {
125 |     const text = await resp.text();
126 |     throw new Error(`watsonx API error (${resp.status}): ${text}`);
127 |   }
128 | 
129 |   const json = await resp.json();
130 |   return json.choices?.[0]?.message?.content ?? json.results?.[0]?.generated_text ?? '';
131 | }
132 | 
133 | // ---------------------------------------------------------------------------
134 | // JSON extraction — parse the last valid JSON object in an LLM response
135 | // ---------------------------------------------------------------------------
136 | 
137 | function extractJSON(text) {
138 |   // Walk backwards looking for the last {...} block
139 |   const last = text.lastIndexOf('}');
140 |   if (last === -1) throw new Error('No JSON object found in response');
141 | 
142 |   let depth = 0;
143 |   let start = -1;
144 |   for (let i = last; i >= 0; i--) {
145 |     if (text[i] === '}') depth++;
146 |     if (text[i] === '{') {
147 |       depth--;
148 |       if (depth === 0) { start = i; break; }
149 |     }
150 |   }
151 |   if (start === -1) throw new Error('Unbalanced JSON in response');
152 | 
153 |   try {
154 |     return JSON.parse(text.slice(start, last + 1));
155 |   } catch (e) {
156 |     throw new Error(`JSON parse error: ${e.message}\n---\n${text.slice(start, last + 1)}`);
157 |   }
158 | }
159 | 
160 | // ---------------------------------------------------------------------------
161 | // File helpers
162 | // ---------------------------------------------------------------------------
163 | 
164 | function readFile(filePath) {
165 |   return fs.existsSync(filePath) ? fs.readFileSync(filePath, 'utf8') : '(file not found)';
166 | }
167 | 
168 | function writeFileAtomic(filePath, content) {
169 |   fs.mkdirSync(path.dirname(filePath), { recursive: true });
170 |   fs.writeFileSync(filePath, content, 'utf8');
171 | }
172 | 
173 | function ensureDir(dir) {
174 |   fs.mkdirSync(dir, { recursive: true });
175 | }
176 | 
177 | // ---------------------------------------------------------------------------
178 | // npm test runner
179 | // ---------------------------------------------------------------------------
180 | 
181 | function runTests() {
182 |   log('  ↳ Running npm test in ' + DEMO_APP_DIR);
183 |   const result = spawnSync('npm', ['test', '--', '--forceExit'], {
184 |     cwd: DEMO_APP_DIR,
185 |     encoding: 'utf8',
186 |     timeout: 120_000,
187 |     shell: true,
188 |   });
189 |   const output = (result.stdout || '') + (result.stderr || '');
190 |   log('  ↳ Test run complete (exit code ' + (result.status ?? 'null') + ')');
191 |   return { output, exitCode: result.status ?? 1 };
192 | }
193 | 
194 | // ---------------------------------------------------------------------------
195 | // Logger
196 | // ---------------------------------------------------------------------------
197 | 
198 | function log(msg) {
199 |   const ts = new Date().toISOString().slice(11, 19);
200 |   console.log(`[${ts}] ${msg}`);
201 | }
202 | 
203 | function banner(title) {
204 |   const line = '─'.repeat(60);
205 |   console.log('\n' + line);
206 |   console.log(`  ${title}`);
207 |   console.log(line);
208 | }
209 | 
210 | // ---------------------------------------------------------------------------
211 | // System prompts (inline, mirrors redteam-orchestrator.md)
212 | // ---------------------------------------------------------------------------
213 | 
214 | const RED_TEAM_SYSTEM = `
215 | You are an elite, adversarial Red Team security engineer. Your sole purpose
216 | is to break the target API. You have no interest in fixing anything — you
217 | exist to discover and prove vulnerabilities.
218 | 
219 | TARGET: POST /api/v1/transfer  (Express.js route in demo-app/routes/transfer.js)
220 | 
221 | YOUR TASK:
222 | Analyse the provided route source and OpenAPI spec.
223 | Then, produce a structured ATTACK REPORT representing what tests you would
224 | run and what vulnerabilities you observe directly from the source code.
225 | Identify every input boundary, type assumption, concurrency window, and
226 | business-logic gap.
227 | 
228 | Output ONLY the following JSON (no prose before or after):
229 | 
230 | {
231 |   "agent": "RED_TEAM",
232 |   "round": <integer>,
233 |   "totalTests": <number of test cases you specify>,
234 |   "passing": <number you predict would pass already>,
235 |   "failing": <number you predict would fail / expose a bug>,
236 |   "testSuite": {
237 |     "fuzzingTests": [
238 |       { "name": "<test name>", "payload": <json object>, "expectedStatus": <number> }
239 |     ],
240 |     "concurrencyTests": [
241 |       { "name": "<test name>", "concurrent": <number>, "payload": <json object>, "expectExactlyOneSuccess": <bool> }
242 |     ]
243 |   },
244 |   "vulnerabilities": [
245 |     {
246 |       "id": "VULN-<n>",
247 |       "severity": "CRITICAL|HIGH|MEDIUM|LOW",
248 |       "description": "<one-sentence description>",
249 |       "payload": "<exact payload that exposes it>",
250 |       "httpStatus": <status code actually or likely returned>,
251 |       "expectedStatus": <correct status code>
252 |     }
253 |   ],
254 |   "rawTestOutput": "<paste first 4000 chars of npm test output here, or NONE if not run>"
255 | }
256 | `.trim();
257 | 
258 | const BLUE_TEAM_SYSTEM = `
259 | You are a defensive Blue Team security engineer. You write the minimum
260 | surgical patch required to close every vulnerability the Red Team found.
261 | You do not rewrite the whole codebase. You do not add features.
262 | 
263 | You will be given the Red Team ATTACK REPORT and the current route source.
264 | 
265 | For each vulnerability, identify the exact lines responsible and write the
266 | minimal guard that closes the vector. Then produce a PATCH REPORT.
267 | 
268 | Output ONLY the following JSON (no prose before or after):
269 | 
270 | {
271 |   "agent": "BLUE_TEAM",
272 |   "round": <same integer as Red Team round>,
273 |   "patchesApplied": <count>,
274 |   "patches": [
275 |     {
276 |       "vulnId":   "<VULN-n>",
277 |       "location": "<line range or function>",
278 |       "strategy": "<one-sentence defence description>",
279 |       "codeDiff": "<the exact lines added or changed>"
280 |     }
281 |   ],
282 |   "updatedRouteSource": "<complete updated content of routes/transfer.js — ALL lines>",
283 |   "notes": "<caveats or residual concerns>"
284 | }
285 | `.trim();
286 | 
287 | const JUDGE_SYSTEM = `
288 | You are an impartial security audit Judge. You hold veto power over the loop.
289 | 
290 | You will be given the Red Team ATTACK REPORT, the Blue Team PATCH REPORT,
291 | and a history array of previous round summaries.
292 | 
293 | Cross-reference every VULN-n in the attack report against the patch report.
294 | Assess whether each patch genuinely closes the vector. Identify any attack
295 | classes not tested that remain obviously open.
296 | 
297 | Output ONLY the following JSON (no prose before or after):
298 | 
299 | {
300 |   "agent": "JUDGE",
301 |   "round": <same integer>,
302 |   "verdict": "APPROVED" | "REJECTED",
303 |   "score": <0–100 security posture score>,
304 |   "approvedVulns": ["<VULN-n>", ...],
305 |   "rejectedVulns": [
306 |     {
307 |       "vulnId": "<VULN-n>",
308 |       "reason": "<why patch is insufficient>",
309 |       "suggestedStrategy": "<hint for Blue Team>"
310 |     }
311 |   ],
312 |   "newConcerns": ["<attack class not yet tested>"],
313 |   "summary": "<2–3 sentence plain-English verdict>"
314 | }
315 | `.trim();
316 | 
317 | // ---------------------------------------------------------------------------
318 | // Agent invocations
319 | // ---------------------------------------------------------------------------
320 | 
321 | async function invokeRedTeam(round, routeSource, openapiSource) {
322 |   banner(`ROUND ${round} — RED TEAM`);
323 |   const userMsg = [
324 |     `Round: ${round}`,
325 |     '',
326 |     '=== routes/transfer.js ===',
327 |     routeSource,
328 |     '',
329 |     '=== openapi.json ===',
330 |     openapiSource,
331 |   ].join('\n');
332 | 
333 |   const response = await chat(RED_TEAM_SYSTEM, userMsg);
334 |   log('  ↳ Red Team response received');
335 |   return extractJSON(response);
336 | }
337 | 
338 | async function invokeBlueTeam(round, attackReport, routeSource) {
339 |   banner(`ROUND ${round} — BLUE TEAM`);
340 |   const userMsg = [
341 |     `Round: ${round}`,
342 |     '',
343 |     '=== ATTACK REPORT ===',
344 |     JSON.stringify(attackReport, null, 2),
345 |     '',
346 |     '=== Current routes/transfer.js ===',
347 |     routeSource,
348 |   ].join('\n');
349 | 
350 |   const response = await chat(BLUE_TEAM_SYSTEM, userMsg);
351 |   log('  ↳ Blue Team response received');
352 |   return extractJSON(response);
353 | }
354 | 
355 | async function invokeJudge(round, attackReport, patchReport, history) {
356 |   banner(`ROUND ${round} — JUDGE`);
357 |   const userMsg = [
358 |     `Round: ${round}`,
359 |     '',
360 |     '=== ATTACK REPORT ===',
361 |     JSON.stringify(attackReport, null, 2),
362 |     '',
363 |     '=== PATCH REPORT ===',
364 |     JSON.stringify(patchReport, null, 2),
365 |     '',
366 |     '=== HISTORY (previous rounds) ===',
367 |     JSON.stringify(history, null, 2),
368 |   ].join('\n');
369 | 
370 |   const response = await chat(JUDGE_SYSTEM, userMsg);
371 |   log('  ↳ Judge response received');
372 |   return extractJSON(response);
373 | }
374 | 
375 | // ---------------------------------------------------------------------------
376 | // Apply Blue Team patch: write the updated route source to disk
377 | // ---------------------------------------------------------------------------
378 | 
379 | function applyPatch(patchReport) {
380 |   const src = patchReport.updatedRouteSource;
381 |   if (!src || typeof src !== 'string' || src.trim().length < 20) {
382 |     log('  ↳ WARNING: Blue Team did not provide updatedRouteSource — skipping file write');
383 |     return;
384 |   }
385 |   writeFileAtomic(ROUTE_FILE, src);
386 |   log(`  ↳ Patch applied → ${ROUTE_FILE}`);
387 | }
388 | 
389 | // ---------------------------------------------------------------------------
390 | // Persist round reports
391 | // ---------------------------------------------------------------------------
392 | 
393 | function saveReport(round, attackReport, patchReport, judgeVerdict) {
394 |   ensureDir(REPORT_DIR);
395 |   const file = path.join(REPORT_DIR, `round-${round}.json`);
396 |   const report = {
397 |     round,
398 |     timestamp: new Date().toISOString(),
399 |     attackReport,
400 |     patchReport,
401 |     judgeVerdict,
402 |   };
403 |   writeFileAtomic(file, JSON.stringify(report, null, 2));
404 |   log(`  ↳ Report saved → ${file}`);
405 |   return report;
406 | }
407 | 
408 | function saveFinalReport(rounds, approved) {
409 |   ensureDir(REPORT_DIR);
410 |   const file = path.join(REPORT_DIR, 'final-audit.json');
411 |   const final = {
412 |     approved,
413 |     totalRounds: rounds.length,
414 |     timestamp: new Date().toISOString(),
415 |     rounds,
416 |   };
417 |   writeFileAtomic(file, JSON.stringify(final, null, 2));
418 |   log(`\n  ↳ Final audit report → ${file}`);
419 | }
420 | 
421 | // ---------------------------------------------------------------------------
422 | // Main orchestration loop
423 | // ---------------------------------------------------------------------------
424 | 
425 | async function main() {
426 |   banner('BreakPoint AI — Orchestrator Starting');
427 |   log(`Demo app: ${DEMO_APP_DIR}`);
428 |   log(`Model:    ${MODEL_ID}`);
429 |   log(`Max rounds: ${MAX_ROUNDS}`);
430 | 
431 |   if (!WATSONX_API_KEY) {
432 |     console.error('\n[ERROR] WATSONX_API_KEY is not set. Export it and retry.\n');
433 |     process.exit(1);
434 |   }
435 |   if (!WATSONX_PROJECT) {
436 |     console.error('\n[ERROR] WATSONX_PROJECT_ID is not set. Export it and retry.\n');
437 |     process.exit(1);
438 |   }
439 | 
440 |   const history = [];
441 |   const allRounds = [];
442 | 
443 |   for (let round = 1; round <= MAX_ROUNDS; round++) {
444 |     log(`\n════ Starting Round ${round} of ${MAX_ROUNDS} ════`);
445 | 
446 |     // Read current state from disk before each round
447 |     const routeSource   = readFile(ROUTE_FILE);
448 |     const openapiSource = readFile(OPENAPI_FILE);
449 | 
450 |     // ── Step 1: Red Team ────────────────────────────────────────────────────
451 |     let attackReport;
452 |     try {
453 |       attackReport = await invokeRedTeam(round, routeSource, openapiSource);
454 |       attackReport.round = round; // normalise
455 |       log(`  Vulnerabilities found: ${(attackReport.vulnerabilities || []).length}`);
456 |     } catch (err) {
457 |       log(`  [ERROR] Red Team invocation failed: ${err.message}`);
458 |       log('  Aborting round — will retry next round');
459 |       continue;
460 |     }
461 | 
462 |     // ── Step 2: Blue Team ───────────────────────────────────────────────────
463 |     let patchReport;
464 |     try {
465 |       patchReport = await invokeBlueTeam(round, attackReport, routeSource);
466 |       patchReport.round = round;
467 |       log(`  Patches applied: ${patchReport.patchesApplied ?? 0}`);
468 |     } catch (err) {
469 |       log(`  [ERROR] Blue Team invocation failed: ${err.message}`);
470 |       log('  Continuing to Judge with empty patch report');
471 |       patchReport = { agent: 'BLUE_TEAM', round, patchesApplied: 0, patches: [], notes: `Error: ${err.message}` };
472 |     }
473 | 
474 |     // Write the patched route to disk
475 |     applyPatch(patchReport);
476 | 
477 |     // ── Step 3: Run the actual test suite against the patched code ──────────
478 |     const { output: testOutput, exitCode } = runTests();
479 |     // Attach real test output to the attack report for Judge context
480 |     attackReport.rawTestOutput = testOutput.slice(0, 4000);
481 |     attackReport.testExitCode  = exitCode;
482 | 
483 |     // ── Step 4: Judge ───────────────────────────────────────────────────────
484 |     let judgeVerdict;
485 |     try {
486 |       judgeVerdict = await invokeJudge(round, attackReport, patchReport, history);
487 |       judgeVerdict.round = round;
488 |     } catch (err) {
489 |       log(`  [ERROR] Judge invocation failed: ${err.message}`);
490 |       judgeVerdict = {
491 |         agent: 'JUDGE', round,
492 |         verdict: 'REJECTED',
493 |         score: 0,
494 |         approvedVulns: [],
495 |         rejectedVulns: [],
496 |         newConcerns: [],
497 |         summary: `Judge error: ${err.message}`,
498 |       };
499 |     }
500 | 
501 |     // Persist round artifacts
502 |     const roundData = saveReport(round, attackReport, patchReport, judgeVerdict);
503 |     allRounds.push(roundData);
504 | 
505 |     // Record a compact summary for Judge history
506 |     history.push({
507 |       round,
508 |       score: judgeVerdict.score,
509 |       verdict: judgeVerdict.verdict,
510 |       vulnCount: (attackReport.vulnerabilities || []).length,
511 |       patchCount: patchReport.patchesApplied ?? 0,
512 |       testExitCode: exitCode,
513 |     });
514 | 
515 |     banner(`ROUND ${round} VERDICT: ${judgeVerdict.verdict}  (score: ${judgeVerdict.score}/100)`);
516 |     log(judgeVerdict.summary || '');
517 | 
518 |     if (judgeVerdict.verdict === 'APPROVED') {
519 |       log('\n✅  APPROVED — all vulnerabilities resolved. Exiting cleanly.\n');
520 |       saveFinalReport(allRounds, true);
521 |       process.exit(0);
522 |     }
523 | 
524 |     if (round < MAX_ROUNDS) {
525 |       log(`\n🔄  REJECTED — proceeding to round ${round + 1}...\n`);
526 |     }
527 |   }
528 | 
529 |   // Exhausted all rounds without approval
530 |   banner('AUDIT FAILED — MAX ROUNDS REACHED');
531 |   log(`❌  The route was NOT approved after ${MAX_ROUNDS} rounds.\n`);
532 |   saveFinalReport(allRounds, false);
533 |   process.exit(1);
534 | }
535 | 
536 | main().catch(err => {
537 |   console.error('\n[FATAL]', err.message);
538 |   process.exit(2);
539 | });
