359 | // ── Helpers ───────────────────────────────────────────────────────────────────
360 | 
361 | interface JestSummary {
362 |   passed: number;
363 |   failed: number;
364 |   total:  number;
365 |   suites: number;
366 | }
367 | 
368 | /**
369 |  * Parses lines like:
370 |  *   Tests:       3 failed, 9 passed, 12 total
371 |  *   Test Suites: 1 failed, 1 passed, 2 total
372 |  */
373 | function parseJestSummary(output: string): JestSummary {
374 |   const result: JestSummary = { passed: 0, failed: 0, total: 0, suites: 0 };
375 | 
376 |   const testsLine  = output.match(/Tests:\s*(.*)/);
377 |   const suitesLine = output.match(/Test Suites:\s*(.*)/);
378 | 
379 |   if (testsLine) {
380 |     const passedM = testsLine[1].match(/(\d+)\s+passed/);
381 |     const failedM = testsLine[1].match(/(\d+)\s+failed/);
382 |     const totalM  = testsLine[1].match(/(\d+)\s+total/);
383 |     if (passedM) result.passed = parseInt(passedM[1], 10);
384 |     if (failedM) result.failed = parseInt(failedM[1], 10);
385 |     if (totalM)  result.total  = parseInt(totalM[1], 10);
386 |   }
387 | 
388 |   if (suitesLine) {
389 |     const totalM = suitesLine[1].match(/(\d+)\s+total/);
390 |     if (totalM) result.suites = parseInt(totalM[1], 10);
391 |   }
392 | 
393 |   return result;
394 | }
395 | 
396 | /**
397 |  * Keeps only the test() blocks that contain at least one matching line.
398 |  * Returns full file content if no pattern matches anything (graceful fallback).
399 |  */
400 | function filterTestBlocks(lines: string[], patterns: RegExp[]): string[] {
401 |   const result: string[] = [];
402 |   let inBlock = false;
403 |   let blockLines: string[] = [];
404 |   let depth = 0;
405 |   let blockMatches = false;
406 | 
407 |   for (const line of lines) {
408 |     const isTestStart = /^\s*(test|it)\s*\(/.test(line);
409 | 
410 |     if (isTestStart && depth === 0) {
411 |       // Save previous block if matched
412 |       if (blockLines.length > 0 && blockMatches) result.push(...blockLines);
413 |       blockLines  = [line];
414 |       blockMatches = patterns.some(p => p.test(line));
415 |       inBlock = true;
416 |       depth = (line.match(/{/g) ?? []).length - (line.match(/}/g) ?? []).length;
417 |       continue;
418 |     }
419 | 
420 |     if (inBlock) {
421 |       blockLines.push(line);
422 |       depth += (line.match(/{/g) ?? []).length - (line.match(/}/g) ?? []).length;
423 |       if (!blockMatches && patterns.some(p => p.test(line))) blockMatches = true;
424 |       if (depth <= 0) {
425 |         if (blockMatches) result.push(...blockLines);
426 |         blockLines  = [];
427 |         blockMatches = false;
428 |         inBlock = false;
429 |         depth   = 0;
430 |       }
431 |     } else {
432 |       // Top-level lines (imports, describe, etc.) always included
433 |       result.push(line);
434 |     }
435 |   }
436 | 
437 |   // Flush last block
438 |   if (blockLines.length > 0 && blockMatches) result.push(...blockLines);
439 | 
440 |   return result.length > 0 ? result : lines; // fallback: return everything
441 | }
