1 | /**
2 |  * BreakPoint AI — C2 Dashboard Server  (v2 — React/SSE edition)
3 |  *
4 |  * Routes
5 |  *   GET  /events          Server-Sent Events stream (all clients)
6 |  *   GET  /events/fuzzer   Dedicated SSE stream for a single MCP fuzzer run.
7 |  *                         Caller POSTs to /run-tests (or MCP calls run_fuzzer),
8 |  *                         then opens this endpoint; the server streams live
9 |  *                         terminal lines and updated radar metrics until the
10 |  *                         Jest child process exits, then sends `done` + closes.
11 |  *   POST /run-tests       Trigger demo-app Jest suite; results stream as SSE
12 |  *   POST /emit            Programmatic SSE injection (used by scripts)
13 |  *   GET  /api/radar       Current Merge Risk Radar dataset
14 |  *   GET  /api/timeline    Persisted threat-mitigation timeline entries
15 |  *   GET  /*               Serves the Vite production build (dist/)
16 |  *
17 |  * SSE event types  (both /events and /events/fuzzer)
18 |  *   log      { type, message, ts }
19 |  *   score    { fuzz, concur, patch }
20 |  *   status   { agent, status }
21 |  *   surface  { transfer, validation, race, auth }
22 |  *   radar    { axes: [{subject, value, fullMark}] }
23 |  *   timeline { id, ts, phase, label, detail, severity }
24 |  *   reset    {}
25 |  *   done     { exitCode, passed, failed }     ← fuzzer stream only
26 |  */
27 | 
28 | 'use strict';
29 | 
30 | const express    = require('express');
31 | const path       = require('path');
32 | const { spawn }  = require('child_process');
33 | const fs         = require('fs');
34 | const chokidar   = require('chokidar');
35 | 
36 | const app  = express();
37 | const PORT = process.env.PORT ?? 4242;
38 | 
39 | // ── Demo state (declared early — addClient references these) ─────────────────
40 | let demoFired    = false;
41 | let demoInterval = null;
42 | 
43 | // ── In-Memory State ───────────────────────────────────────────────────────────
44 | 
45 | /** @type {{ axes: {subject:string,value:number,fullMark:number}[] }} */
46 | let radarData = {
47 |   axes: [
48 |     { subject: 'Input Validation', value: 0,  fullMark: 100 },
49 |     { subject: 'Race Conditions',  value: 0,  fullMark: 100 },
50 |     { subject: 'Auth Bypass',      value: 0,  fullMark: 100 },
51 |     { subject: 'Payload Fuzzing',  value: 0,  fullMark: 100 },
52 |     { subject: 'Error Handling',   value: 0,  fullMark: 100 },
53 |     { subject: 'Patch Coverage',   value: 0,  fullMark: 100 },
54 |   ],
55 | };
56 | 
57 | /** @type {Array<{id:string,ts:number,phase:string,label:string,detail:string,severity:string}>} */
58 | let timelineEntries = [];
59 | 
60 | let timelineSeq = 0;
61 | function pushTimeline(phase, label, detail, severity = 'info') {
62 |   const entry = {
63 |     id:       `tl-${++timelineSeq}`,
64 |     ts:       Date.now(),
65 |     phase,
66 |     label,
67 |     detail,
68 |     severity,
69 |   };
70 |   timelineEntries.push(entry);
71 |   if (timelineEntries.length > 120) timelineEntries.shift();
72 |   broadcast('timeline', entry);
73 |   return entry;
74 | }
