76 | // ── SSE Client Registry ───────────────────────────────────────────────────────
77 | /** @type {Map<string, import('http').ServerResponse>} */
78 | const clients = new Map();
79 | 
80 | function addClient(res) {
81 |   // Each new browser connection resets the demo so late-joiners see the sequence
82 |   demoFired = false;
83 |   setTimeout(fireDemo, 1500);
84 |   const id = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
85 |   res.set({
86 |     'Content-Type':      'text/event-stream',
87 |     'Cache-Control':     'no-cache',
88 |     'Connection':        'keep-alive',
89 |     'X-Accel-Buffering': 'no',
90 |   });
91 |   res.flushHeaders();
92 |   const heartbeat = setInterval(() => res.write(': ping\n\n'), 20_000);
93 |   res.on('close', () => { clearInterval(heartbeat); clients.delete(id); });
94 |   clients.set(id, res);
95 |   return id;
96 | }
97 | 
98 | function broadcast(event, data) {
99 |   const payload = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
100 |   for (const res of clients.values()) {
101 |     try { res.write(payload); } catch (_) { /* client gone */ }
102 |   }
103 | }
104 | 
105 | // ── Middleware ────────────────────────────────────────────────────────────────
106 | app.use(express.json());
107 | 
108 | // Serve Vite production build
109 | const DIST = path.join(__dirname, 'client', 'dist');
110 | if (fs.existsSync(DIST)) {
111 |   app.use(express.static(DIST));
112 | } else {
113 |   // Fall back to old static files during development
114 |   app.use(express.static(path.join(__dirname)));
115 | }
