117 | // ── REST API ──────────────────────────────────────────────────────────────────
118 | 
119 | app.get('/api/radar', (_req, res) => res.json(radarData));
120 | 
121 | app.get('/api/timeline', (_req, res) => res.json(timelineEntries));
122 | 
123 | // ── SSE endpoint ──────────────────────────────────────────────────────────────
124 | app.get('/events', (req, res) => {
125 |   const id = addClient(res);
126 |   res.write(`event: log\ndata: ${JSON.stringify({
127 |     type: 'system',
128 |     message: `C2 channel established — client ${id.slice(0, 8)}`,
129 |     ts: Date.now(),
130 |   })}\n\n`);
131 |   // Send current radar snapshot
132 |   res.write(`event: radar\ndata: ${JSON.stringify(radarData)}\n\n`);
133 | });
134 | 
135 | // ── Trigger test run ──────────────────────────────────────────────────────────
136 | app.post('/run-tests', (req, res) => {
137 |   res.json({ ok: true, message: 'Test run triggered' });
138 |   runDemoTests();
139 | });
140 | 
141 | // ── Programmatic inject ───────────────────────────────────────────────────────
142 | app.post('/emit', (req, res) => {
143 |   const { event, data } = req.body ?? {};
144 |   if (!event || !data) return res.status(400).json({ error: 'event and data required' });
145 |   broadcast(event, { ...data, ts: data.ts ?? Date.now() });
146 |   res.json({ ok: true });
147 | });
148 | 
149 | // ── Fuzzer SSE stream ─────────────────────────────────────────────────────────
150 | //
151 | // GET /events/fuzzer
152 | //
153 | // Opens a per-request SSE channel and immediately spawns (or reuses an already-
154 | // running) Jest child process.  Every stdout/stderr line is forwarded as a `log`
155 | // event; when the child exits the updated radar axes are emitted as a `radar`
156 | // event followed by a `done` event, then the response is closed.
157 | //
158 | // The endpoint is intentionally stateless — each HTTP connection gets its own
159 | // isolated run so the MCP tool and the React dashboard never share a mutable
160 | // subprocess handle.
161 | 
162 | app.get('/events/fuzzer', (req, res) => {
163 |   // ── SSE headers ──────────────────────────────────────────────────────────
164 |   res.set({
165 |     'Content-Type':      'text/event-stream',
166 |     'Cache-Control':     'no-cache',
167 |     'Connection':        'keep-alive',
168 |     'X-Accel-Buffering': 'no',
169 |   });
170 |   res.flushHeaders();
171 | 
172 |   // Keep-alive heartbeat so proxies / load-balancers don't close the socket
173 |   const heartbeat = setInterval(() => res.write(': ping\n\n'), 20_000);
174 | 
175 |   /** Emit a named SSE event to this response only. */
176 |   function send(event, data) {
177 |     if (!res.writableEnded) {
178 |       res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
179 |     }
180 |   }

