180 |   }
181 | 
182 |   /** Close this SSE channel cleanly. */
183 |   function finish() {
184 |     clearInterval(heartbeat);
185 |     if (!res.writableEnded) res.end();
186 |   }
187 | 
188 |   // Abort if the client disconnects before the run finishes
189 |   req.on('close', finish);
190 | 
191 |   // ── Announce stream open ──────────────────────────────────────────────────
192 |   send('log', { type: 'system', message: '── Fuzzer stream connected — starting Jest run ──', ts: Date.now() });
193 | 
194 |   // ── Guard: demo-app must exist ────────────────────────────────────────────
195 |   if (!fs.existsSync(path.join(DEMO_APP_DIR, 'package.json'))) {
196 |     send('log', { type: 'fail', message: `demo-app not found at ${DEMO_APP_DIR}`, ts: Date.now() });
197 |     send('done', { exitCode: 1, passed: 0, failed: 0 });
198 |     finish();
199 |     return;
200 |   }
201 | 
202 |   // ── Spawn Jest ────────────────────────────────────────────────────────────
203 |   const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm';
204 | 
205 |   // Forward optional query params from the MCP tool / dashboard:
206 |   //   ?pattern=<jest -t pattern>
207 |   //   ?timeout=<ms>
208 |   const testPattern = typeof req.query.pattern === 'string' ? req.query.pattern : null;
209 |   const timeoutMs   = Number(req.query.timeout) || 60_000;
210 | 
211 |   const args = ['test', '--', '--detectOpenHandles', '--forceExit', '--no-coverage'];
212 |   if (testPattern) args.push('-t', testPattern);
213 | 
214 |   const child = spawn(npm, args, {
215 |     cwd:   DEMO_APP_DIR,
216 |     env:   { ...process.env, FORCE_COLOR: '0', CI: 'true' },
217 |     shell: true,
218 |   });
219 | 
220 |   // Kill the child if the client drops the connection mid-run
221 |   req.on('close', () => { try { child.kill('SIGTERM'); } catch (_) {} });
222 | 
223 |   let stdoutBuf  = '';
224 |   let stderrBuf  = '';
225 |   let passCount  = 0;
226 |   let failCount  = 0;
227 |   let http500Count = 0;
228 | 
229 |   // ── ANSI stripper ─────────────────────────────────────────────────────────
230 |   const stripAnsi = s => s.replace(/\x1B\[[0-9;]*m/g, '');
231 | 
232 |   // ── Stream stdout line-by-line ────────────────────────────────────────────
233 |   child.stdout.on('data', chunk => {
234 |     stdoutBuf += chunk.toString();
235 |     const lines = stdoutBuf.split('\n');
236 |     stdoutBuf = lines.pop(); // keep incomplete last line in buffer
237 |     for (const raw of lines) {
238 |       const line = stripAnsi(raw).trim();
239 |       if (!line) continue;
240 | 
241 |       const classified = classifyJestLine(line);
242 |       send('log', { type: classified.type, message: classified.message, ts: Date.now() });
243 | 
244 |       // Also broadcast to all connected /events clients so the main dashboard
245 |       // stays in sync when a fuzzer run is initiated from the MCP tool.
246 |       broadcast('log', { type: classified.type, message: classified.message, ts: Date.now() });
247 | 
248 |       if (classified.type === 'pass') passCount++;
249 |       if (classified.type === 'fail') failCount++;
250 | 
251 |       if (/500|internal server/i.test(line)) {
252 |         http500Count++;
253 |         send('log', { type: 'fail', message: `HTTP 500 — ${line}`, ts: Date.now() });
254 |         broadcast('log', { type: 'fail', message: `HTTP 500 — ${line}`, ts: Date.now() });
255 |         pushTimeline('Fuzzing', 'HTTP 500 Detected', line, 'critical');
256 |       }
257 |       if (/payload|fuzz/i.test(line))   pushTimeline('Fuzzing', 'Payload Fired',      line, 'warn');
258 |       if (/patch|validat|lock|fix/i.test(line)) pushTimeline('Patch', 'Mitigation Applied', line, 'success');
259 |     }
260 |   });
261 | 
262 |   // ── Stream stderr line-by-line ────────────────────────────────────────────
263 |   child.stderr.on('data', chunk => {
264 |     stderrBuf += chunk.toString();
265 |     const lines = stderrBuf.split('\n');
