272 |       broadcast('log', { type: classified.type, message: classified.message, ts: Date.now() });
273 |       if (classified.type === 'pass') passCount++;
274 |       if (classified.type === 'fail') failCount++;
275 |       if (/500|internal server/i.test(line)) {
276 |         http500Count++;
277 |         send('log',      { type: 'fail', message: `HTTP 500 — ${line}`, ts: Date.now() });
278 |         broadcast('log', { type: 'fail', message: `HTTP 500 — ${line}`, ts: Date.now() });
