475 | // ── Jest Output Classifier ────────────────────────────────────────────────────
476 | function classifyJestLine(line) {
477 |   if (/✓|✔|PASS|passed/i.test(line))               return { type: 'pass',    message: line };
478 |   if (/✕|✗|✘|FAIL|failed|Error|throw/i.test(line)) return { type: 'fail',    message: line };
479 |   if (/warn|deprecat/i.test(line))                  return { type: 'warn',    message: line };
480 |   if (/payload|fuzz|inject|null|negativ/i.test(line)) return { type: 'payload', message: line };
481 |   if (/patch|validat|lock|fix/i.test(line))         return { type: 'patch',   message: line };
482 |   return { type: 'info', message: line };
483 | }
