489 |     const rel = path.relative(DEMO_APP_DIR, filePath);
490 |     broadcast('log', { type: 'system', message: `New test file detected: ${rel}`, ts: Date.now() });
491 |     pushTimeline('Discovery', 'New Test File', rel, 'info');
