}

// ── REST API ──────────────────────────────────────────────────────────────────

app.get('/api/radar', (_req, res) => res.json(radarData));

app.get('/api/timeline', (_req, res) => res.json(timelineEntries));

// ── SSE endpoint ──────────────────────────────────────────────────────────────
app.get('/events', (req, res) => {
  const id = addClient(res);
