  const targets = mentionedRels.size > 0
    ? sourceFiles.filter(f => {
        const rel = path.relative(targetDir, f).replace(/\\/g, '/');
        return [...mentionedRels].some(m => rel.endsWith(m) || m.endsWith(rel));
