// ── Main export ────────────────────────────────────────────────────────────────
module.exports = async function audit(targetDir, options = {}) {
  const {
    rounds    = 5,
    model     = process.env.MODEL_ID || 'ibm/granite-3-3-8b-instruct',
    outputDir = path.join(targetDir, '.breakpoint', 'audit-reports'),
