'use strict';
const { collectSourceFiles, runAstRules, getSupportedExtensions, shouldSkipFile } = require('./lib/scan-lib');
const path = require('path');

let passed = 0;
let failed = 0;

function assert(label, actual, expected) {
  if (actual === expected) {
    console.log(`  ✅  ${label}`);
    passed++;
  } else {
    console.log(`  ❌  ${label}  — expected ${JSON.stringify(expected)}, got ${JSON.stringify(actual)}`);
    failed++;
  }
}

console.log('\n── Test 1: Supported extensions ─────────────────────────────');
const exts = getSupportedExtensions();
assert('has .py',   exts.includes('.py'),   true);
assert('has .java', exts.includes('.java'), true);
assert('has .go',   exts.includes('.go'),   true);
assert('has .php',  exts.includes('.php'),  true);
assert('has .rb',   exts.includes('.rb'),   true);
assert('has .cs',   exts.includes('.cs'),   true);
assert('has .rs',   exts.includes('.rs'),   true);
assert('has .js',   exts.includes('.js'),   true);

console.log('\n── Test 2: Binary / oversized file guard ────────────────────');
assert('skip .pyc',             shouldSkipFile('foo.pyc',    { size: 100 }),    true);
assert('skip .class',           shouldSkipFile('Foo.class',  { size: 100 }),    true);
assert('skip .jar',             shouldSkipFile('lib.jar',    { size: 1000 }),   true);
assert('skip 600 KB bundle.js', shouldSkipFile('bundle.js',  { size: 620000 }), true);
assert('allow 10 KB app.py',    shouldSkipFile('app.py',     { size: 10000 }),  false);
assert('allow 10 KB app.js',    shouldSkipFile('app.js',     { size: 10000 }),  false);
assert('allow 10 KB Main.java', shouldSkipFile('Main.java',  { size: 10000 }),  false);

console.log('\n── Test 3: Minified file skipped ────────────────────────────');
const minifiedSrc = 'var a=1;' + 'x'.repeat(3000);
const findings_minified = runAstRules('app.js', minifiedSrc);
assert('minified JS produces 0 findings', findings_minified.length, 0);

console.log('\n── Test 4: Extension filter (py rules only on .py) ──────────');
const pyCode = 'eval(user_input)';
assert('py-eval on .js = 0', runAstRules('test.js', pyCode).filter(f => f.rule === 'py-eval').length, 0);
assert('py-eval on .py = 1', runAstRules('test.py', pyCode).filter(f => f.rule === 'py-eval').length, 1);

const jsCode = 'eval("user_code")';
assert('eval-usage on .py = 0',  runAstRules('test.py', jsCode).filter(f => f.rule === 'eval-usage').length,  0);
assert('eval-usage on .js = 1',  runAstRules('test.js', jsCode).filter(f => f.rule === 'eval-usage').length,  1);

console.log('\n── Test 5: Language rules fire correctly ─────────────────────');
// Java
const javaCode = 'stmt.executeQuery("SELECT * FROM users WHERE id = " + request.getParameter("id"))';
assert('java-sql-injection fires', runAstRules('User.java', javaCode).filter(f => f.rule === 'java-sql-injection').length, 1);
assert('java-sql on .py = 0',      runAstRules('app.py',    javaCode).filter(f => f.rule === 'java-sql-injection').length, 0);

// PHP
const phpCode = 'echo $_GET["name"];';
assert('php-xss fires',    runAstRules('index.php', phpCode).filter(f => f.rule === 'php-xss').length, 1);
assert('php-xss on .js=0', runAstRules('index.js',  phpCode).filter(f => f.rule === 'php-xss').length, 0);

// Python Flask debug
const flaskCode = 'app.run(debug=True, port=5000)';
assert('py-flask-debug fires',     runAstRules('app.py', flaskCode).filter(f => f.rule === 'py-flask-debug').length, 1);
assert('py-flask-debug on .rb=0',  runAstRules('app.rb', flaskCode).filter(f => f.rule === 'py-flask-debug').length, 0);

// Go
const goCode = 'db.Query("SELECT * FROM users WHERE name = " + r.FormValue("name"))';
assert('go-sql-injection fires',    runAstRules('main.go', goCode).filter(f => f.rule === 'go-sql-injection').length, 1);
assert('go-sql on .cs = 0',         runAstRules('main.cs', goCode).filter(f => f.rule === 'go-sql-injection').length, 0);

// Rust unsafe
const rustCode = 'unsafe { *ptr = 42; }';
assert('rust-unsafe-block fires',   runAstRules('main.rs', rustCode).filter(f => f.rule === 'rust-unsafe-block').length, 1);

console.log('\n── Test 6: Case-insensitive extension matching ───────────────');
// collectSourceFiles uses lowercase normalisation — files named .PY should match .py
// Simulate by calling runAstRules with uppercase ext in path
const pyFindingUppercase = runAstRules('APP.PY', flaskCode);
assert('APP.PY matches .py rules', pyFindingUppercase.filter(f => f.rule === 'py-flask-debug').length, 1);

console.log('\n── Test 7: audit buildSourceContext budget ───────────────────');
const { } = require('./lib/audit'); // just check it imports without error
console.log('  ✅  audit.js imports cleanly');
passed++;

console.log(`\n${'─'.repeat(55)}`);
console.log(`Result: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);

