1 | #!/usr/bin/env node
2 | /**
3 |  * ci-fuzzer.js — BreakPoint AI CI gate
4 |  *
5 |  * 1. Runs the full Jest suite (fuzzing + concurrency) inside demo-app/.
6 |  * 2. Parses the output into a structured Merge Confidence Scorecard.
7 |  * 3. Posts the scorecard as a PR comment via the GitHub REST API.
8 |  * 4. Exits with code 1 if any test failed (blocks the merge).
9 |  *
10 |  * Required env vars (all injected by the Actions workflow):
11 |  *   GITHUB_TOKEN          – Actions token with `pull-requests: write`
12 |  *   GITHUB_REPOSITORY     – "owner/repo"
13 |  *   PR_NUMBER             – pull request number
14 |  *
15 |  * Optional:
16 |  *   DEMO_APP_DIR          – absolute path to demo-app/ (default: auto-resolved)
17 |  *   TEST_TIMEOUT_MS       – Jest timeout cap in ms (default: 90000)
18 |  */
19 | 
20 | 'use strict';
21 | 
22 | const { spawnSync } = require('child_process');
23 | const https         = require('https');
24 | const path          = require('path');
25 | 
26 | // ---------------------------------------------------------------------------
27 | // Config
28 | // ---------------------------------------------------------------------------
29 | const DEMO_APP_DIR   = process.env.DEMO_APP_DIR
30 |   ?? path.resolve(__dirname, '..', 'demo-app');
31 | 
32 | const TIMEOUT_MS     = parseInt(process.env.TEST_TIMEOUT_MS ?? '90000', 10);
33 | const GITHUB_TOKEN   = process.env.GITHUB_TOKEN;
34 | const REPO           = process.env.GITHUB_REPOSITORY;   // "owner/repo"
35 | const PR_NUMBER      = process.env.PR_NUMBER;
36 | 
37 | // ---------------------------------------------------------------------------
38 | // Run Jest
39 | // ---------------------------------------------------------------------------
40 | function runJest() {
41 |   console.log(`[breakpoint-ci] Running Jest in ${DEMO_APP_DIR} …`);
42 | 
43 |   const npm = process.platform === 'win32' ? 'npm.cmd' : 'npm';
44 |   const result = spawnSync(
45 |     npm,
46 |     ['test', '--', '--forceExit', '--detectOpenHandles', '--no-coverage', '--ci'],
47 |     {
48 |       cwd:      DEMO_APP_DIR,
49 |       encoding: 'utf8',
50 |       timeout:  TIMEOUT_MS,
51 |       env:      { ...process.env, FORCE_COLOR: '0', CI: 'true' },
52 |       shell:    false,
53 |     }
54 |   );
55 | 
56 |   const raw    = (result.stdout ?? '') + '\n' + (result.stderr ?? '');
57 |   const clean  = raw.replace(/\x1B\[[0-9;]*m/g, '');   // strip ANSI
58 |   const exitCode = result.status ?? 1;
59 | 
60 |   console.log(clean);
61 |   return { clean, exitCode };
62 | }
