64 | // ---------------------------------------------------------------------------
65 | // Parse Jest output
66 | // ---------------------------------------------------------------------------
67 | function parseSummary(output) {
68 |   const summary = { passed: 0, failed: 0, total: 0, suites: 0 };
69 | 
70 |   const testsLine  = output.match(/Tests:\s*(.*)/);
71 |   const suitesLine = output.match(/Test Suites:\s*(.*)/);
72 | 
73 |   if (testsLine) {
74 |     const p = testsLine[1].match(/(\d+)\s+passed/);
75 |     const f = testsLine[1].match(/(\d+)\s+failed/);
76 |     const t = testsLine[1].match(/(\d+)\s+total/);
77 |     if (p) summary.passed = parseInt(p[1], 10);
78 |     if (f) summary.failed = parseInt(f[1], 10);
79 |     if (t) summary.total  = parseInt(t[1], 10);
80 |   }
81 |   if (suitesLine) {
82 |     const t = suitesLine[1].match(/(\d+)\s+total/);
83 |     if (t) summary.suites = parseInt(t[1], 10);
84 |   }
85 | 
86 |   return summary;
87 | }
88 | 
89 | /** Extract individual failed test names from Jest output. */
90 | function parseFailedTests(output) {
91 |   const failed = [];
92 |   // Jest marks failures with "● <suite name> › <test name>"
93 |   const re = /^[\s]*●\s+(.+)$/gm;
94 |   let m;
95 |   while ((m = re.exec(output)) !== null) {
96 |     const name = m[1].trim();
97 |     // Skip sub-bullets that are error detail lines (contain "expect(")
98 |     if (!name.includes('expect(') && !name.startsWith('at ')) {
99 |       failed.push(name);
100 |     }
101 |   }
102 |   return [...new Set(failed)];
103 | }
104 | 
105 | // ---------------------------------------------------------------------------
106 | // Build Merge Confidence Scorecard (Markdown)
107 | // ---------------------------------------------------------------------------
108 | function buildScorecard(summary, failedTests, exitCode, durationMs) {
109 |   const verdict      = exitCode === 0;
110 |   const passRate     = summary.total > 0
111 |     ? ((summary.passed / summary.total) * 100).toFixed(1)
112 |     : '0.0';
113 |   const confidence   = verdict ? computeConfidence(summary) : 0;
114 | 
115 |   const statusBadge  = verdict
116 |     ? '🟢 **PASSED** — safe to merge'
117 |     : '🔴 **FAILED** — merge blocked';
118 | 
119 |   const confBar      = buildBar(confidence);
120 | 
121 |   const failBlock    = failedTests.length > 0
122 |     ? `\n### ❌ Failing Tests\n${failedTests.map(t => `- \`${t}\``).join('\n')}\n`
123 |     : '';
124 | 
125 |   const vulnWarning  = !verdict
126 |     ? `\n> ⚠️ **Vulnerability Detected** — BreakPoint AI identified ${summary.failed} failing security ` +
127 |       `test${summary.failed !== 1 ? 's' : ''}. Review the failures above before merging.\n`
128 |     : '';
129 | 
130 |   return [
131 |     `## 🛡️ BreakPoint AI — Merge Confidence Scorecard`,
132 |     ``,
133 |     `| Field | Value |`,
134 |     `|---|---|`,
135 |     `| **Status** | ${statusBadge} |`,
136 |     `| **Merge Confidence** | ${confBar} ${confidence}% |`,
137 |     `| **Tests Passed** | ${summary.passed} / ${summary.total} (${passRate}%) |`,
138 |     `| **Tests Failed** | ${summary.failed} |`,
139 |     `| **Test Suites** | ${summary.suites} |`,
140 |     `| **Duration** | ${(durationMs / 1000).toFixed(1)} s |`,
141 |     ``,
142 |     vulnWarning,
143 |     failBlock,
144 |     `<details>`,
145 |     `<summary>What is this?</summary>`,
146 |     ``,
147 |     `BreakPoint AI runs an automated fuzzing and concurrency-attack suite against every`,
148 |     `pull request. It checks for input-validation bypasses, SQL/NoSQL injection, negative`,
149 |     `amounts, race conditions, and double-spend vulnerabilities. A non-zero exit code`,
150 |     `blocks the merge until all security tests pass.`,
151 |     ``,
152 |     `</details>`,
153 |     ``,
154 |     `---`,
155 |     `*Generated by [BreakPoint AI](https://github.com/apps/breakpoint-ai) · ${new Date().toUTCString()}*`,
156 |   ].join('\n');
157 | }
158 | 
159 | function computeConfidence(summary) {
160 |   if (summary.total === 0) return 0;
161 |   return Math.round((summary.passed / summary.total) * 100);
162 | }
163 | 
164 | function buildBar(pct) {
165 |   const filled = Math.round(pct / 10);
166 |   const empty  = 10 - filled;
167 |   return '█'.repeat(filled) + '░'.repeat(empty);
168 | }
169 | 
170 | // ---------------------------------------------------------------------------
171 | // Post GitHub PR comment
172 | // ---------------------------------------------------------------------------
173 | async function postComment(body) {
174 |   if (!GITHUB_TOKEN || !REPO || !PR_NUMBER) {
175 |     console.warn('[breakpoint-ci] GitHub env vars not set — skipping comment.');
176 |     return;
177 |   }
178 | 
179 |   const [owner, repoName] = REPO.split('/');
180 |   const payload = JSON.stringify({ body });
181 |   const url     = `https://api.github.com/repos/${owner}/${repoName}/issues/${PR_NUMBER}/comments`;
182 | 
183 |   console.log(`[breakpoint-ci] Posting scorecard to ${url} …`);
184 | 
185 |   return new Promise((resolve, reject) => {
186 |     const options = {
187 |       method:   'POST',
188 |       hostname: 'api.github.com',
189 |       path:     `/repos/${owner}/${repoName}/issues/${PR_NUMBER}/comments`,
190 |       headers:  {
191 |         'Content-Type':    'application/json',
192 |         'Content-Length':  Buffer.byteLength(payload),
193 |         'Authorization':   `Bearer ${GITHUB_TOKEN}`,
194 |         'Accept':          'application/vnd.github+json',
195 |         'X-GitHub-Api-Version': '2022-11-28',
196 |         'User-Agent':      'BreakPoint-AI-CI/1.0',
197 |       },
198 |     };
199 | 
200 |     const req = https.request(options, res => {
201 |       let data = '';
202 |       res.on('data', chunk => { data += chunk; });
203 |       res.on('end', () => {
204 |         if (res.statusCode >= 200 && res.statusCode < 300) {
205 |           console.log(`[breakpoint-ci] Comment posted (HTTP ${res.statusCode}).`);
206 |           resolve();
207 |         } else {
208 |           console.error(`[breakpoint-ci] GitHub API error ${res.statusCode}: ${data}`);
209 |           reject(new Error(`GitHub API responded with ${res.statusCode}`));
210 |         }
211 |       });
212 |     });
213 | 
214 |     req.on('error', reject);
215 |     req.write(payload);
216 |     req.end();
217 |   });
218 | }
219 | 
220 | // ---------------------------------------------------------------------------
221 | // Main
222 | // ---------------------------------------------------------------------------
223 | async function main() {
224 |   const t0 = Date.now();
225 | 
226 |   const { clean, exitCode } = runJest();
227 |   const duration   = Date.now() - t0;
228 |   const summary    = parseSummary(clean);
229 |   const failedTests = parseFailedTests(clean);
230 | 
231 |   const scorecard  = buildScorecard(summary, failedTests, exitCode, duration);
232 | 
233 |   console.log('\n' + '─'.repeat(60));
234 |   console.log(scorecard);
235 |   console.log('─'.repeat(60) + '\n');
236 | 
237 |   // Write the scorecard to a file so the workflow can upload it as an artifact
238 |   const fs = require('fs');
239 |   const outPath = path.join(__dirname, '..', 'breakpoint-scorecard.md');
240 |   fs.writeFileSync(outPath, scorecard, 'utf8');
241 |   console.log(`[breakpoint-ci] Scorecard written to ${outPath}`);
242 | 
243 |   try {
244 |     await postComment(scorecard);
245 |   } catch (err) {
246 |     // A comment failure is non-fatal — the exit code still gates the merge
247 |     console.error('[breakpoint-ci] Failed to post comment:', err.message);
248 |   }
249 | 
250 |   if (exitCode !== 0) {
251 |     console.error(
252 |       `[breakpoint-ci] ❌ ${summary.failed} test(s) failed. Exiting with code 1 to block merge.`
253 |     );
254 |     process.exit(1);
255 |   }
256 | 
257 |   console.log('[breakpoint-ci] ✅ All tests passed. Merge confidence: 100%');
258 |   process.exit(0);
259 | }
260 | 
