1 | /**
2 |  * useSSE — custom hook that connects to the Express SSE endpoint and
3 |  * dispatches all named events into a single reducer-based state object.
4 |  *
5 |  * useFuzzerStream — companion hook that opens the dedicated /events/fuzzer
6 |  * SSE channel whenever `active` flips to true.  Live terminal lines are
7 |  * appended to the shared reducer via the LOG action; the final `radar` event
8 |  * updates MergeRiskRadar in real time; the `done` event marks the run as
9 |  * finished and the EventSource is closed.
10 |  *
11 |  * Usage in App.jsx:
12 |  *   const [fuzzerActive, setFuzzerActive] = useState(false);
13 |  *   const { isFuzzing, lastResult } = useFuzzerStream(dispatch, fuzzerActive, {
14 |  *     pattern: 'Fuzzing',   // optional: jest -t pattern
15 |  *   });
16 |  */
17 | import { useEffect, useReducer, useCallback, useRef, useState } from 'react';
18 | 
19 | const MAX_LOG_LINES    = 500;
20 | const MAX_TIMELINE     = 150;
21 | 
22 | const INITIAL = {
23 |   serverStatus:  'connecting',   // connecting | online | offline
24 |   logs:          [],
25 |   stats:         { total: 0, pass: 0, fail: 0, warn: 0 },
26 |   score:         { fuzz: null, concur: null, patch: null },
27 |   surface:       { transfer: 'unknown', validation: 'unknown', race: 'unknown', auth: 'unknown' },
28 |   agents:        { A: 'idle', B: 'idle' },
29 |   radarAxes:     [],
30 |   timeline:      [],
31 | };
32 | 
33 | function reducer(state, action) {
34 |   switch (action.type) {
35 |     case 'SERVER_STATUS':
36 |       return { ...state, serverStatus: action.status };
37 | 
38 |     case 'LOG': {
39 |       const { type, message, ts } = action.data;
40 |       const newStats = { ...state.stats, total: state.stats.total + 1 };
41 |       if (type === 'pass') newStats.pass++;
42 |       else if (type === 'fail') newStats.fail++;
43 |       else if (type === 'warn') newStats.warn++;
44 |       const entry = { id: `${ts}-${Math.random()}`, type, message, ts };
45 |       const logs = [...state.logs, entry];
46 |       if (logs.length > MAX_LOG_LINES) logs.splice(0, logs.length - MAX_LOG_LINES);
47 |       return { ...state, logs, stats: newStats };
48 |     }
49 | 
50 |     case 'SCORE':
51 |       return {
52 |         ...state,
53 |         score: {
54 |           fuzz:   action.data.fuzz   ?? state.score.fuzz,
55 |           concur: action.data.concur ?? state.score.concur,
56 |           patch:  action.data.patch  ?? state.score.patch,
57 |         },
58 |       };
59 | 
60 |     case 'STATUS':
61 |       return { ...state, agents: { ...state.agents, [action.data.agent]: action.data.status } };
62 | 
63 |     case 'SURFACE':
64 |       return { ...state, surface: { ...state.surface, ...action.data } };
65 | 
66 |     case 'RADAR':
67 |       return { ...state, radarAxes: action.data.axes ?? [] };
68 | 
69 |     case 'TIMELINE': {
70 |       const entries = [...state.timeline, action.data];
71 |       if (entries.length > MAX_TIMELINE) entries.shift();
72 |       return { ...state, timeline: entries };
73 |     }
74 | 
75 |     case 'RESET':
76 |       return { ...INITIAL, serverStatus: state.serverStatus };
77 | 
78 |     default:
79 |       return state;
80 |   }
81 | }
82 | 
83 | export function useSSE() {
84 |   const [state, dispatch] = useReducer(reducer, INITIAL);
85 | 
86 |   const connect = useCallback(() => {
87 |     dispatch({ type: 'SERVER_STATUS', status: 'connecting' });
88 |     const es = new EventSource('/events');
89 | 
90 |     es.onopen  = () => dispatch({ type: 'SERVER_STATUS', status: 'online' });
91 |     es.onerror = () => {
92 |       dispatch({ type: 'SERVER_STATUS', status: 'offline' });
93 |       es.close();
94 |       setTimeout(connect, 3000);
95 |     };
96 | 
97 |     es.addEventListener('log',      e => dispatch({ type: 'LOG',      data: JSON.parse(e.data) }));
98 |     es.addEventListener('score',    e => dispatch({ type: 'SCORE',    data: JSON.parse(e.data) }));
99 |     es.addEventListener('status',   e => dispatch({ type: 'STATUS',   data: JSON.parse(e.data) }));
100 |     es.addEventListener('surface',  e => dispatch({ type: 'SURFACE',  data: JSON.parse(e.data) }));
101 |     es.addEventListener('radar',    e => dispatch({ type: 'RADAR',    data: JSON.parse(e.data) }));
102 |     es.addEventListener('timeline', e => dispatch({ type: 'TIMELINE', data: JSON.parse(e.data) }));
103 |     es.addEventListener('reset',    () => dispatch({ type: 'RESET' }));
104 | 
105 |     return es;
106 |   }, []);
107 | 
108 |   useEffect(() => {
109 |     const es = connect();
110 |     return () => es.close();
111 |   }, [connect]);
112 | 
113 |   // Fetch initial radar + timeline on mount
114 |   useEffect(() => {
115 |     fetch('/api/radar').then(r => r.json()).then(data => {
116 |       dispatch({ type: 'RADAR', data });
117 |     }).catch(() => {});
118 |     fetch('/api/timeline').then(r => r.json()).then(entries => {
119 |       entries.forEach(e => dispatch({ type: 'TIMELINE', data: e }));
120 |     }).catch(() => {});
121 |   }, []);
122 | 
123 |   // Expose dispatch so App.jsx can pass it to useFuzzerStream without
124 |   // duplicating state or adding a React context.
125 |   return { ...state, dispatch };
126 | }
