132 | /**
133 |  * Opens `GET /events/fuzzer` as an EventSource whenever `active` is true.
134 |  * Feeds every received event directly into the caller-supplied `dispatch`
135 |  * (the same dispatcher returned by `useSSE`'s internal useReducer) so the
136 |  * LiveLog and MergeRiskRadar update without any extra state or prop drilling.
137 |  *
138 |  * @param {function}  dispatch  - The `dispatch` function from useSSE's reducer.
139 |  *                                Pass it down from App via a context or a ref.
140 |  * @param {boolean}   active    - Set to true to start the run; false to ignore.
141 |  * @param {object}    [opts]
142 |  * @param {string}    [opts.pattern]  - Optional Jest -t filter pattern.
143 |  * @param {number}    [opts.timeout]  - Max ms before Jest is killed (default 60000).
144 |  *
145 |  * @returns {{ isFuzzing: boolean, lastResult: {exitCode,passed,failed}|null }}
146 |  */
147 | export function useFuzzerStream(dispatch, active, opts = {}) {
148 |   const [isFuzzing,  setIsFuzzing]  = useState(false);
149 |   const [lastResult, setLastResult] = useState(null);
150 | 
151 |   // Keep a stable ref to opts so the effect doesn't re-run on every render
152 |   // when the caller passes an inline object literal.
153 |   const optsRef = useRef(opts);
154 |   useEffect(() => { optsRef.current = opts; }, [opts]);
155 | 
156 |   useEffect(() => {
157 |     if (!active) return;
158 | 
