  // the user clicks "Run Tests" and returns to false when the `done` event
  // arrives (or on error / unmount).
  const [fuzzerActive, setFuzzerActive] = useState(false);

  const { isFuzzing } = useFuzzerStream(dispatch, fuzzerActive, {
