    env:   { ...process.env, FORCE_COLOR: '0' },
    shell: true,
  });

  let stdout = '';
  let stderr = '';
  let passCount = 0;
  let failCount = 0;
  let http500Count = 0;

  child.stdout.on('data', chunk => {
    stdout += chunk.toString();
