1 | /**
2 |  * useSSE — custom hook that connects to the Express SSE endpoint and
3 |  * dispatches all named events into a single reducer-based state object.
4 |  */
5 | import { useEffect, useReducer, useCallback } from 'react';
6 | 
7 | const MAX_LOG_LINES    = 500;
8 | const MAX_TIMELINE     = 150;
9 | 
10 | const INITIAL = {
11 |   serverStatus:  'connecting',   // connecting | online | offline
12 |   logs:          [],
13 |   stats:         { total: 0, pass: 0, fail: 0, warn: 0 },
14 |   score:         { fuzz: null, concur: null, patch: null },
15 |   surface:       { transfer: 'unknown', validation: 'unknown', race: 'unknown', auth: 'unknown' },
16 |   agents:        { A: 'idle', B: 'idle' },
17 |   radarAxes:     [],
18 |   timeline:      [],
19 | };
20 | 
21 | function reducer(state, action) {
22 |   switch (action.type) {
23 |     case 'SERVER_STATUS':
24 |       return { ...state, serverStatus: action.status };
25 | 
26 |     case 'LOG': {
27 |       const { type, message, ts } = action.data;
28 |       const newStats = { ...state.stats, total: state.stats.total + 1 };
29 |       if (type === 'pass') newStats.pass++;
30 |       else if (type === 'fail') newStats.fail++;
31 |       else if (type === 'warn') newStats.warn++;
32 |       const entry = { id: `${ts}-${Math.random()}`, type, message, ts };
33 |       const logs = [...state.logs, entry];
34 |       if (logs.length > MAX_LOG_LINES) logs.splice(0, logs.length - MAX_LOG_LINES);
35 |       return { ...state, logs, stats: newStats };
36 |     }
37 | 
38 |     case 'SCORE':
39 |       return {
40 |         ...state,
41 |         score: {
42 |           fuzz:   action.data.fuzz   ?? state.score.fuzz,
43 |           concur: action.data.concur ?? state.score.concur,
44 |           patch:  action.data.patch  ?? state.score.patch,
45 |         },
46 |       };
47 | 
48 |     case 'STATUS':
49 |       return { ...state, agents: { ...state.agents, [action.data.agent]: action.data.status } };
50 | 
51 |     case 'SURFACE':
52 |       return { ...state, surface: { ...state.surface, ...action.data } };
53 | 
54 |     case 'RADAR':
55 |       return { ...state, radarAxes: action.data.axes ?? [] };
56 | 
57 |     case 'TIMELINE': {
58 |       const entries = [...state.timeline, action.data];
59 |       if (entries.length > MAX_TIMELINE) entries.shift();
60 |       return { ...state, timeline: entries };
61 |     }
62 | 
63 |     case 'RESET':
64 |       return { ...INITIAL, serverStatus: state.serverStatus };
65 | 
66 |     default:
67 |       return state;
68 |   }
69 | }
70 | 
71 | export function useSSE() {
72 |   const [state, dispatch] = useReducer(reducer, INITIAL);
73 | 
74 |   const connect = useCallback(() => {
75 |     dispatch({ type: 'SERVER_STATUS', status: 'connecting' });
76 |     const es = new EventSource('/events');
77 | 
78 |     es.onopen  = () => dispatch({ type: 'SERVER_STATUS', status: 'online' });
79 |     es.onerror = () => {
80 |       dispatch({ type: 'SERVER_STATUS', status: 'offline' });
81 |       es.close();
82 |       setTimeout(connect, 3000);
83 |     };
84 | 
85 |     es.addEventListener('log',      e => dispatch({ type: 'LOG',      data: JSON.parse(e.data) }));
86 |     es.addEventListener('score',    e => dispatch({ type: 'SCORE',    data: JSON.parse(e.data) }));
87 |     es.addEventListener('status',   e => dispatch({ type: 'STATUS',   data: JSON.parse(e.data) }));
88 |     es.addEventListener('surface',  e => dispatch({ type: 'SURFACE',  data: JSON.parse(e.data) }));
89 |     es.addEventListener('radar',    e => dispatch({ type: 'RADAR',    data: JSON.parse(e.data) }));
90 |     es.addEventListener('timeline', e => dispatch({ type: 'TIMELINE', data: JSON.parse(e.data) }));
91 |     es.addEventListener('reset',    () => dispatch({ type: 'RESET' }));
92 | 
93 |     return es;
94 |   }, []);
95 | 
96 |   useEffect(() => {
97 |     const es = connect();
98 |     return () => es.close();
99 |   }, [connect]);
100 | 
101 |   // Fetch initial radar + timeline on mount
102 |   useEffect(() => {
103 |     fetch('/api/radar').then(r => r.json()).then(data => {
104 |       dispatch({ type: 'RADAR', data });
105 |     }).catch(() => {});
106 |     fetch('/api/timeline').then(r => r.json()).then(entries => {
107 |       entries.forEach(e => dispatch({ type: 'TIMELINE', data: e }));
108 |     }).catch(() => {});
109 |   }, []);
110 | 
111 |   return state;
112 | }
