const checks = [
  ['on: pull_request', /^on:/m.test(content)],
  ['pull_request trigger', /pull_request/.test(content)],
  ['permissions block', /permissions:/.test(content)],
  ['pull-requests: write', /pull-requests: write/.test(content)],
