Contents of file breakpoint-ai/dashboard/server.js:

1 | /**
2 |  * BreakPoint AI — C2 Dashboard Server
3 |  *
4 |  * Serves the static dashboard and provides:
5 |  *   GET  /events      — Server-Sent Events stream (all connected clients)
6 |  *   POST /run-tests   — Triggers the demo-app test suite and streams results
7 |  *   POST /emit        — Programmatic injection endpoint (for scripts)
8 |  *
9 |  * The server also watches ../demo-app/tests/ for new .test.js files using
10 |  * chokidar and auto-announces them as SSE log events.
11 |  */
12 | 
13 | 'use strict';
14 | 
15 | const express  = require('express');
16 | const path     = require('path');
17 | const { spawn } = require('child_process');
18 | const fs       = require('fs');
19 | const chokidar = require('chokidar');
20 | 
21 | const app  = express();
22 | const PORT = process.env.PORT ?? 4242;
23 | 
24 | // ── SSE Client Registry ───────────────────────────────────────────────────────
25 | /** @type {Map<string, import('http').ServerResponse>} */
26 | const clients = new Map();
27 | 
28 | function addClient(res) {
29 |   const id = `${Date.now()}-${Math.random().toString(36).slice(2)}`;
30 |   res.set({
31 |     'Content-Type':  'text/event-stream',
32 |     'Cache-Control': 'no-cache',
33 |     'Connection':    'keep-alive',
34 |     'X-Accel-Buffering': 'no',
35 |   });
36 |   res.flushHeaders();
37 |   // Heartbeat every 20 s to keep connections alive through proxies
38 |   const heartbeat = setInterval(() => res.write(': ping\n\n'), 20_000);
39 |   res.on('close', () => { clearInterval(heartbeat); clients.delete(id); });
40 |   clients.set(id, res);
41 |   return id;
42 | }
43 | 
44 | /**
45 |  * Broadcast an SSE event to every connected client.
46 |  * @param {string} event  Named event type (log | score | status | surface | reset)
47 |  * @param {object} data
48 |  */
49 | function broadcast(event, data) {
50 |   const payload = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
51 |   for (const res of clients.values()) {
52 |     try { res.write(payload); } catch (_) { /* client gone */ }
53 |   }
54 | }
55 | 
56 | // ── Middleware ────────────────────────────────────────────────────────────────
57 | app.use(express.json());
58 | app.use(express.static(path.join(__dirname)));      // serves index.html + dashboard.js
59 | 
60 | // ── Routes ────────────────────────────────────────────────────────────────────
61 | 
62 | // SSE endpoint
63 | app.get('/events', (req, res) => {
64 |   const id = addClient(res);
65 |   // Send welcome event
66 |   const payload = `event: log\ndata: ${JSON.stringify({
67 |     type: 'system',
68 |     message: `C2 channel established — client ${id.slice(0,8)}`,
69 |     ts: Date.now(),
70 |   })}\n\n`;
71 |   res.write(payload);
72 | });
73 | 
74 | // Trigger test run
75 | app.post('/run-tests', (req, res) => {
76 |   res.json({ ok: true, message: 'Test run triggered' });
77 |   runDemoTests();
78 | });
79 | 
80 | // Programmatic inject (used by test scripts via: POST /emit { event, data })
81 | app.post('/emit', (req, res) => {
82 |   const { event, data } = req.body ?? {};
83 |   if (!event || !data) return res.status(400).json({ error: 'event and data required' });
84 |   broadcast(event, { ...data, ts: data.ts ?? Date.now() });
85 |   res.json({ ok: true });
86 | });
87 | 
88 | // ── Test Runner ───────────────────────────────────────────────────────────────
89 | const DEMO_APP_DIR = path.resolve(__dirname, '..', 'demo-app');
90 | 
91 | function runDemoTests() {
92 |   broadcast('log', { type: 'system', message: '── Test run starting ──', ts: Date.now() });
93 |   broadcast('status', { agent: 'A', status: 'running' });
94 |   broadcast('status', { agent: 'B', status: 'running' });
95 |   broadcast('surface', { transfer: 'scanning', validation: 'scanning', race: 'scanning', auth: 'unknown' });
96 | 
97 |   // Validate demo-app exists
