function classifyJestLine(line) {
  if (/✓|✔|PASS|passed/i.test(line))          return { type: 'pass',    message: line };
  if (/✕|✗|✘|FAIL|failed|Error|throw/i.test(line)) return { type: 'fail', message: line };
