  ],
};

/** @type {Array<{id:string,ts:number,phase:string,label:string,detail:string,severity:string}>} */
let timelineEntries = [];

let timelineSeq = 0;
function pushTimeline(phase, label, detail, severity = 'info') {
  const entry = {
    id:       `tl-${++timelineSeq}`,
    ts:       Date.now(),
    phase,
    label,
    detail,
