  scanning:   'bg-amber-500/10 text-amber-400 border-amber-500/30',
  clean:      'bg-cyan-500/10 text-cyan-400 border-cyan-500/30',
  unknown:    'bg-gray-700 text-gray-400 border-gray-600',
};
const BADGE_LABEL = {
  vulnerable: 'VULNERABLE',
  patched:    'PATCHED',
