  banner('AUDIT FAILED — MAX ROUNDS REACHED');
  log(`❌  The route was NOT approved after ${MAX_ROUNDS} rounds.\n`);
  saveFinalReport(allRounds, false);
  process.exit(1);
}

main().catch(err => {
  console.error('\n[FATAL]', err.message);
  process.exit(2);
});

