+  const el = document.getElementById(map[agent]);
+  if (!el) return;
+
+  const colors = { running: 'text-cyan-400', done: 'text-green-400', error: 'text-red-400', idle: 'text-gray-500' };
+  el.textContent = status;
+  el.className = colors[status] ?? 'text-gray-500';
