app.post('/emit', (req, res) => {
  const { event, data } = req.body ?? {};
  if (!event || !data) return res.status(400).json({ error: 'event and data required' });
  broadcast(event, { ...data, ts: data.ts ?? Date.now() });
  res.json({ ok: true });
});

