        const abs = path.resolve(DEMO_APP_DIR, file_path);
        args.push(abs);
      } else {
        args.push(DEMO_APP_DIR);
      }

      const { stdout, stderr } = await execFileAsync("git", args, {
        cwd: WORKSPACE_ROOT,
        maxBuffer: 2 * 1024 * 1024, // 2 MB
      });

